import { renderMarkdownInline } from '../../../common/markdown';

/**
 * Live preview of a perk card (Бонус Лучшего or a manual perk), as it would
 * render on the forum. Shared by BestBonusSection and ManualPerkGroupCard.
 */
export default function PerkPreviewCard(props) {
  const label = props.label,
    icon = props.icon,
    color = props.color,
    description = props.description;
  return m("div", {
    className: "RolevayaPreviewCard"
  }, m("div", {
    className: "RolevayaPreviewCard-top"
  }, m("div", {
    className: "RolevayaPreviewCard-icon",
    style: {
      color
    }
  }, m("i", {
    className: icon || 'fa-solid fa-star',
    "aria-hidden": "true"
  })), m("div", {
    className: "RolevayaPreviewCard-meta"
  }, m("div", {
    className: "RolevayaPreviewCard-title"
  }, label || 'Название дара'), m("div", {
    className: "RolevayaPreviewCard-subtitle"
  }, "\u041F\u0440\u0435\u0434\u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0438"))), m("div", {
    className: "RolevayaPreviewCard-body"
  }, description ? renderMarkdownInline(description) : 'Описание дара появится здесь. Можно использовать Markdown.'));
}
flarum.reg.add('forumaker-rolevaya', 'admin/components/settings/PerkPreviewCard', PerkPreviewCard);